import os
import json

session_line = sorted(os.listdir('/home/USER/runs/paper/qwen-ha-u1-turns/frozen/seen-2/play/users/u070/system/state/sessions'))[-1]
session_path = f'/home/USER/runs/paper/qwen-ha-u1-turns/frozen/seen-2/play/users/u070/system/state/sessions/{session_line}'

with open(session_path) as f:
    lines = f.readlines()

# Find all submit actions and their outcomes
print("Looking for submit actions with results...")
submit_results = {}
for line in lines:
    try:
        data = json.loads(line)
        if 'metadata' in data and 'action' in data.get('metadata', {}):
            data = data['metadata']
        elif 'result' in data:
            data = data.get('result', {})

        if data and isinstance(data, dict):
            action = data.get('action', data.get('tools', []))
            if action and isinstance(action, list):
                for a in action:
                    if a and isinstance(a, dict) and a.get('name') == 'submit':
                        # Found a submit, check for result
                        if 'result' in data:
                            result = data['result']
                            error = result.get('error', None)
                            output = result.get('output', None)

                            if error:
                                print(f"SUBMIT FAILED: {error.get('message', 'unknown')}")
                            elif output:
                                print(f"SUBMIT OUTPUT: {output[:200]}")
                            else:
                                print("SUBMIT with no error or output")
    except:
        pass

# Also search for failures
print("\nSearching for failure patterns...")
for line in lines:
    data = json.loads(line) if line.strip() else {}
    data = data.get('metadata', data.get('result', {}))
    if isinstance(data, dict):
        error = data.get('error')
        msg = data.get('message', '')
        if error and isinstance(error, str):
            if 'ACTION_REPORT' in msg or 'submit' in msg.lower():
                print(f"Error: {msg[:200]}")

